{"policy":"permit (
    principal is Person,
    action == Action::"clearSecurityCheck",
    resource is SecurityCheck
)
when {
    principal.roles.contains(Role::"BackgroundInvestigator") &&
    resource.status == "pending" &&
    context.currentTime.greaterThanOrEqual(resource.permittedWindowStart) &&
    context.currentTime.lessThanOrEqual(resource.permittedWindowEnd)
};

permit (
    principal is Person,
    action == Action::"clearSecurityCheck",
    resource is SecurityCheck
)
when {
    principal.roles.contains(Role::"SupervisoryOfficer") &&
    context.currentTime.greaterThanOrEqual(resource.permittedWindowStart) &&
    context.currentTime.lessThanOrEqual(resource.permittedWindowEnd)
};

forbid (
    principal is Person,
    action == Action::"clearSecurityCheck",
    resource is SecurityCheck
)
when {
    (principal.roles.contains(Role::"BackgroundInvestigator") ||
     principal.roles.contains(Role::"SupervisoryOfficer")) &&
    !(context.currentTime.greaterThanOrEqual(resource.permittedWindowStart) &&
      context.currentTime.lessThanOrEqual(resource.permittedWindowEnd))
};"}
